'use client';

import React, { useRef, useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { productsData, categoriesData, CategoryItem, ProductItem } from '@/app/data/products';
import './HorizontalScrollContainer.css';

export type { CategoryItem, ProductItem };

export const CategoryChip: React.FC<{
  item: CategoryItem;
  isSelected: boolean;
  onClick: () => void;
}> = ({ item, isSelected, onClick }) => (
  <button
    className={`chip-button ${isSelected ? 'active' : ''}`}
    onClick={onClick}
  >
    {item.icon && <span className="chip-icon">{item.icon}</span>}
    <span>{item.label}</span>
  </button>
);

export const ProductCard: React.FC<{
  product: ProductItem;
  onProductClick?: (product: ProductItem) => void;
}> = ({ product, onProductClick }) => (
  <div 
    className="product-card" 
    onClick={() => onProductClick?.(product)} 
    style={{ cursor: 'pointer' }}
  >
    {product.badge && <span className="product-badge">{product.badge}</span>}
    <div className="product-image-box">
      <img src={product.image} alt={product.title} draggable={false} />
    </div>
    <div className="product-details">
      <h4 className="product-title">{product.title}</h4>
      <div className="product-price-box">
        <span className="current-price">{product.price}</span>
        {product.originalPrice && (
          <span className="old-price">{product.originalPrice}</span>
        )}
      </div>
      {product.rating && <div className="product-rating">⭐ {product.rating}</div>}
    </div>
  </div>
);

interface HorizontalScrollContainerProps {
  categories?: CategoryItem[];
  products?: ProductItem[];
  scrollAmount?: number;
  onSelectProduct?: (product: ProductItem) => void;
}

export const HorizontalScrollContainer: React.FC<HorizontalScrollContainerProps> = ({
  categories = categoriesData,
  products = productsData,
  scrollAmount = 300,
  onSelectProduct,
}) => {
  const router = useRouter();
  const categoryRef = useRef<HTMLDivElement | null>(null);
  const productRef = useRef<HTMLDivElement | null>(null);

  const [selectedCategoryId, setSelectedCategoryId] = useState<string | number>(
    categories.find((c) => c.active)?.id || categories[0]?.id
  );

  // منطق الفلترة: يعرض كافة المنتجات إذا كانت قيمة المعرف 'all' أو 0، وإلا يفلتر حسب categoryId أو category
  const filteredProducts = products.filter((product: any) => {
    if (!selectedCategoryId || selectedCategoryId === 'all' || selectedCategoryId === 0) {
      return true;
    }
    return (
      product.categoryId === selectedCategoryId || 
      product.category === selectedCategoryId
    );
  });

  useEffect(() => {
    const el = productRef.current;
    if (!el) return;

    let isDown = false;
    let startY = 0;
    let scrollTop = 0;

    const onMouseDown = (e: MouseEvent) => {
      isDown = true;
      el.classList.add('dragging');
      startY = e.pageY - el.offsetTop;
      scrollTop = el.scrollTop;
    };

    const onMouseLeaveOrUp = () => {
      isDown = false;
      el.classList.remove('dragging');
    };

    const onMouseMove = (e: MouseEvent) => {
      if (!isDown) return;
      e.preventDefault();
      const y = e.pageY - el.offsetTop;
      const walk = (y - startY) * 1.5;
      el.scrollTop = scrollTop - walk;
    };

    el.addEventListener('mousedown', onMouseDown);
    el.addEventListener('mouseleave', onMouseLeaveOrUp);
    el.addEventListener('mouseup', onMouseLeaveOrUp);
    el.addEventListener('mousemove', onMouseMove);

    return () => {
      el.removeEventListener('mousedown', onMouseDown);
      el.removeEventListener('mouseleave', onMouseLeaveOrUp);
      el.removeEventListener('mouseup', onMouseLeaveOrUp);
      el.removeEventListener('mousemove', onMouseMove);
    };
  }, []);

  const handleVerticalScroll = (direction: 'up' | 'down') => {
    if (!productRef.current) return;
    const offset = direction === 'up' ? -scrollAmount : scrollAmount;
    productRef.current.scrollBy({ top: offset, behavior: 'smooth' });
  };

  const handleHorizontalScroll = (direction: 'left' | 'right') => {
    if (!categoryRef.current) return;
    const offset = direction === 'left' ? -200 : 200;
    categoryRef.current.scrollBy({ left: offset, behavior: 'smooth' });
  };

  return (
    <div className="section-wrapper">
      <div className="scroll-wrapper categories-wrapper">
        <button
          className="scroll-btn left-btn"
          onClick={() => handleHorizontalScroll('left')}
        >
          &#10094;
        </button>
        <div className="horizontal-scroll-container" ref={categoryRef}>
          <div className="horizontal-scroll-content">
            {categories.map((cat) => (
              <CategoryChip
                key={cat.id}
                item={cat}
                isSelected={selectedCategoryId === cat.id}
                onClick={() => setSelectedCategoryId(cat.id)}
              />
            ))}
          </div>
        </div>
        <button
          className="scroll-btn right-btn"
          onClick={() => handleHorizontalScroll('right')}
        >
          &#10095;
        </button>
      </div>

      <div className="vertical-scroll-wrapper">
        <button
          className="v-scroll-btn top-btn"
          onClick={() => handleVerticalScroll('up')}
        >
          &#9679;
        </button>

        <div className="vertical-scroll-container" ref={productRef}>
          <div className="products-grid">
            {filteredProducts.length > 0 ? (
              filteredProducts.map((prod) => (
                <ProductCard
                  key={prod.id}
                  product={prod}
                  onProductClick={(p) => {
                    if (onSelectProduct) {
                      onSelectProduct(p);
                    } else {
                      router.push(`/product/${p.id}`);
                    }
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                  }}
                />
              ))
            ) : (
              <p style={{ padding: '20px', textAlign: 'center', width: '100%' }}>
                لا توجد منتجات في هذا التصنيف.
              </p>
            )}
          </div>
        </div>

        <button
          className="v-scroll-btn bottom-btn"
          onClick={() => handleVerticalScroll('down')}
        >
          &#9679;
        </button>
      </div>
    </div>
  );
};

export default HorizontalScrollContainer;